// ── CONFIG ───────────────────────────────────────────────
const DROP_THRESHOLD_PERCENT = 50;   // alert if today < 50% of avg
const ROLLING_DAYS           = 7;    // how many past days to average
const MIN_AVG_TO_ALERT       = 0.5;    // skip alert if avg itself is < 1
// ─────────────────────────────────────────────────────────

const rows  = $input.all();
const today = new Date();

// normalise any date string → "YYYY-MM-DD"
function toDateKey(raw) {
  if (!raw) return null;
  const s = String(raw).trim();

  // handle DD/MM/YYYY  or  MM/DD/YYYY  or  ISO
  let d;
  if (/^\d{2}\/\d{2}\/\d{4}/.test(s)) {
    const [p1, p2, p3] = s.split('/');
    // your sheet uses DD/MM/YYYY  — adjust if MM/DD/YYYY
    d = new Date(`${p3}-${p2}-${p1}`);
  } else {
    d = new Date(s);
  }
  if (isNaN(d)) return null;
  return d.toISOString().slice(0, 10);          // "YYYY-MM-DD"
}

function dateKey(d) {
  return d.toISOString().slice(0, 10);
}

// ── BUILD DAILY COUNT MAP ────────────────────────────────
const countByDate = {};

for (const row of rows) {
  const raw = row.json['Timestamp'] ?? row.json['timestamp'] ?? '';
  const key = toDateKey(raw);
  if (!key) continue;
  countByDate[key] = (countByDate[key] || 0) + 1;
}

// ── TODAY'S COUNT ────────────────────────────────────────
const todayKey   = dateKey(today);
const todayCount = countByDate[todayKey] || 0;

// ── ROLLING AVERAGE (past N days, excluding today) ───────
const pastCounts = [];
for (let i = 1; i <= ROLLING_DAYS; i++) {
  const d = new Date(today);
  d.setDate(d.getDate() - i);
  const k = dateKey(d);
  pastCounts.push(countByDate[k] || 0);
}

const rollingSum = pastCounts.reduce((a, b) => a + b, 0);
const rollingAvg = rollingSum / ROLLING_DAYS;

// ── DROP DETECTION ───────────────────────────────────────
const dropPercent   = rollingAvg > 0
  ? Math.round(((rollingAvg - todayCount) / rollingAvg) * 100)
  : 0;

const isDropAlert   = rollingAvg  >= MIN_AVG_TO_ALERT &&
                      todayCount  <  rollingAvg * (1 - DROP_THRESHOLD_PERCENT / 100);
const isZeroAlert   = todayCount === 0 && rollingAvg >= MIN_AVG_TO_ALERT;

// ── CHANNEL BREAKDOWN FOR TODAY ──────────────────────────
const channelBreakdown = {};
for (const row of rows) {
  const key = toDateKey(row.json['Timestamp'] ?? '');
  if (key !== todayKey) continue;
  const ch = row.json['Channel'] || 'Unknown';
  channelBreakdown[ch] = (channelBreakdown[ch] || 0) + 1;
}

// ── SOURCE BREAKDOWN FOR TODAY ───────────────────────────
const sourceBreakdown = {};
for (const row of rows) {
  const key = toDateKey(row.json['Timestamp'] ?? '');
  if (key !== todayKey) continue;
  const src = row.json['Source'] || 'Direct/Unknown';
  sourceBreakdown[src] = (sourceBreakdown[src] || 0) + 1;
}

// ── BEST DAY IN ROLLING WINDOW ───────────────────────────
let bestDay = '', bestCount = 0;
for (let i = 1; i <= ROLLING_DAYS; i++) {
  const d = new Date(today);
  d.setDate(d.getDate() - i);
  const k = dateKey(d);
  if ((countByDate[k] || 0) > bestCount) {
    bestCount = countByDate[k];
    bestDay   = k;
  }
}

// ── SEVERITY ─────────────────────────────────────────────
let severity = 'NORMAL';
if (isZeroAlert)                         severity = 'CRITICAL';
else if (isDropAlert && dropPercent > 70) severity = 'HIGH';
else if (isDropAlert)                     severity = 'WARNING';

// ── OUTPUT ───────────────────────────────────────────────
return [{
  json: {
    todayKey,
    todayCount,
    rollingAvg:         Math.round(rollingAvg * 10) / 10,
    dropPercent:        Math.max(dropPercent, 0),
    isDropAlert,
    isZeroAlert,
    severity,
    channelBreakdown,
    sourceBreakdown,
    bestDay,
    bestCount,
    rollingWindow:      ROLLING_DAYS,
    thresholdUsed:      DROP_THRESHOLD_PERCENT,
    dailyCountMap:      countByDate,
  }
}];

